// A type of your own: describe how to flatten and rebuild it.
data class DateRange(val fromEpochDay: Long, val toEpochDay: Long)

private val DateRangeSaver = listSaver<DateRange, Long>(
    save = { listOf(it.fromEpochDay, it.toEpochDay) },
    restore = { DateRange(it[0], it[1]) },
)

// Saving the value itself.
val range = rememberSaveable(saver = DateRangeSaver) { defaultRange() }

// Saving a MutableState of it, so it can be written to as well.
var range by rememberSaveable(stateSaver = DateRangeSaver) {
    mutableStateOf(defaultRange())
}

