class FilterPanelState(
    initialQuery: String = "",
) {
    var query by mutableStateOf(initialQuery)
        private set
    var selectedTags by mutableStateOf(emptySet<String>())
        private set

    val canApply: Boolean
        get() = query.isNotBlank() || selectedTags.isNotEmpty()

    fun onQueryChange(value: String) { query = value }

    fun onTagToggled(tag: String) {
        selectedTags = if (tag in selectedTags) selectedTags - tag else selectedTags + tag
    }
}

@Composable
fun rememberFilterPanelState(): FilterPanelState = remember { FilterPanelState() }

