var filters by remember { mutableStateOf(Filters()) }

// Mutates the list inside; the holder is never written. Nothing updates.
filters.tags.add("kotlin")

// Assigns, but `copy()` is shallow: the new instance shares the same list, and
// the default structural-equality policy finds the two instances equal, so this
// still schedules nothing.
filters = filters.copy().also { it.tags.add("kotlin") }

